@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun EditUpcomingTaskDialog(
    task: TaskEntity,
    onDismiss: () -> Unit,
    onSave: (title: String, difficulty: Difficulty, scheduledDate: LocalDate?, reminderHour: Int?, reminderMinute: Int?, pesterEnabled: Boolean, pesterIntervalMinutes: Int?, notes: String?) -> Unit,
    pesterModeEnabled: Boolean = false
) {
    var titleText by remember { mutableStateOf(task.title) }
    var selectedDifficulty by remember { mutableStateOf(task.difficulty) }
    var scheduledDate by remember { mutableStateOf(task.scheduledDateEpochDay?.let(LocalDate::ofEpochDay)) }
    var showDatePicker by remember { mutableStateOf(false) }
    var notesExpanded by remember { mutableStateOf(!task.notes.isNullOrBlank()) }
    var notesText by remember { mutableStateOf(task.notes ?: "") }
    var reminderEnabled by remember { mutableStateOf(task.reminderHour != null && task.reminderMinute != null) }
    var reminderHour by remember { mutableIntStateOf(task.reminderHour ?: 9) }
    var reminderMinute by remember { mutableIntStateOf(task.reminderMinute ?: 0) }
    var pesterEnabled by remember { mutableStateOf(task.pesterEnabled) }
    var pesterIntervalMinutes by remember { mutableIntStateOf(task.pesterIntervalMinutes ?: 15) }

    GoblinAlertDialog(
        onDismissRequest = onDismiss,
        title = {
            Text(stringResource(R.string.edit_quest_title), fontWeight = FontWeight.ExtraBold, color = MaterialTheme.colorScheme.primary)
        },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                OutlinedTextField(
                    value = titleText,
                    onValueChange = { titleText = it },
                    placeholder = { Text(stringResource(R.string.quest_title_placeholder)) },
                    modifier = Modifier.fillMaxWidth(),
                    singleLine = true,
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = MaterialTheme.colorScheme.primary,
                        unfocusedBorderColor = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.2f)
                    )
                )

                Text(stringResource(R.string.loot_level_label), style = MaterialTheme.typography.bodySmall, fontWeight = FontWeight.SemiBold, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f))
                DifficultySelector(selectedDifficulty = selectedDifficulty, onSelect = { selectedDifficulty = it })

                Row(
                    modifier = Modifier
                        .clip(RoundedCornerShape(6.dp))
                        .clickable { notesExpanded = !notesExpanded }
                        .padding(vertical = 4.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Icon(
                        if (notesExpanded) Icons.Filled.KeyboardArrowUp else Icons.Filled.KeyboardArrowDown,
                        contentDescription = stringResource(R.string.toggle_notes_content_description),
                        tint = MaterialTheme.colorScheme.primary.copy(alpha = 0.7f),
                        modifier = Modifier.size(16.dp)
                    )
                    Spacer(modifier = Modifier.width(4.dp))
                    Text(stringResource(R.string.notes_optional_label), fontSize = 12.sp, fontWeight = FontWeight.SemiBold, color = MaterialTheme.colorScheme.primary.copy(alpha = 0.7f))
                }

                AnimatedVisibility(visible = notesExpanded) {
                    OutlinedTextField(
                        value = notesText,
                        onValueChange = { notesText = it },
                        placeholder = { Text(stringResource(R.string.quest_notes_placeholder)) },
                        modifier = Modifier.fillMaxWidth(),
                        minLines = 3,
                        maxLines = 5,
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = MaterialTheme.colorScheme.primary,
                            unfocusedBorderColor = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.2f)
                        )
                    )
                }

                HorizontalDivider(color = MaterialTheme.colorScheme.surfaceVariant)

                ScheduledDateRow(
                    scheduledDate = scheduledDate,
                    onPickDate = { showDatePicker = true },
                    onClearDate = { scheduledDate = null }
                )

                HorizontalDivider(color = MaterialTheme.colorScheme.surfaceVariant)

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(stringResource(R.string.set_a_reminder_label), fontWeight = FontWeight.SemiBold, fontSize = 14.sp, color = MaterialTheme.colorScheme.onSurface)
                    Switch(checked = reminderEnabled, onCheckedChange = { reminderEnabled = it })
                }

                if (reminderEnabled) {
                    TimePickerRow(label = stringResource(R.string.label_alert_at), hour = reminderHour, minute = reminderMinute, onTimeChanged = { h, m -> reminderHour = h; reminderMinute = m })

                    if (pesterModeEnabled) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(stringResource(R.string.pester_me_toggle), fontWeight = FontWeight.SemiBold, fontSize = 14.sp, color = MaterialTheme.colorScheme.onSurface)
                            Switch(checked = pesterEnabled, onCheckedChange = { pesterEnabled = it })
                        }

                        if (pesterEnabled) {
                            PesterIntervalStepper(minutes = pesterIntervalMinutes, onMinutesChange = { pesterIntervalMinutes = it })
                        }
                    }
                }
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    if (titleText.isNotBlank()) {
                        onSave(
                            titleText.trim(),
                            selectedDifficulty,
                            scheduledDate,
                            if (reminderEnabled) reminderHour else null,
                            if (reminderEnabled) reminderMinute else null,
                            reminderEnabled && pesterEnabled,
                            if (reminderEnabled && pesterEnabled) pesterIntervalMinutes else null,
                            notesText.trim().ifBlank { null }
                        )
                    }
                },
                enabled = titleText.isNotBlank()
            ) {
                Text(stringResource(R.string.action_save), fontWeight = FontWeight.ExtraBold)
            }
        },
        dismissButton = { TextButton(onClick = onDismiss) { Text(stringResource(R.string.action_cancel)) } }
    )

    if (showDatePicker) {
        GoblinDatePickerDialog(
            initialDate = scheduledDate ?: LocalDate.now(),
            onDismiss = { showDatePicker = false },
            onDateSelected = { scheduledDate = it },
            selectableDates = object : SelectableDates {
                override fun isSelectableDate(utcTimeMillis: Long): Boolean {
                    val today = LocalDate.now().atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli()
                    return utcTimeMillis >= today
                }
            }
        )
    }
}
